import { TestBed } from '@angular/core/testing';
import { ApplicationRef } from '@angular/core';
import { WatchlistStore } from './watchlist-store';
import { TmdbMovie } from './movie';

function makeMovie(overrides: Partial<TmdbMovie> = {}): TmdbMovie {
  return {
    id: 42,
    title: 'The Movie',
    release_date: '2024-01-01',
    poster_path: '/poster.jpg',
    overview: 'An epic movie.',
    ...overrides,
  };
}

// Let microtask-scheduled effects (Angular v19+) flush, then also run change
// detection so effect schedulers that flush during ApplicationRef.tick()
// (Angular v16 - v18) get a chance to persist the watchlist.
async function flushEffects(): Promise<void> {
  await Promise.resolve();
  TestBed.inject(ApplicationRef).tick();
  await Promise.resolve();
}

describe('WatchlistStore', () => {
  let service: WatchlistStore;

  beforeEach(() => {
    localStorage.clear();
    TestBed.configureTestingModule({});
    service = TestBed.inject(WatchlistStore);
  });

  it('should be created', () => {
    expect(service).toBeTruthy();
  });

  it('adds a movie with seen set to false', () => {
    service.add(makeMovie());

    expect(service.items()).toEqual([
      { id: 42, title: 'The Movie', poster_path: '/poster.jpg', release_date: '2024-01-01', seen: false },
    ]);
    expect(service.count()).toBe(1);
    expect(service.watchedCount()).toBe(0);
  });

  it('ignores movies that are already on the watchlist', () => {
    service.add(makeMovie());
    service.add(makeMovie({ title: 'Same Movie, Same Id' }));

    expect(service.items()).toHaveLength(1);
    expect(service.count()).toBe(1);
  });

  it('flips the seen flag when toggleWatched is called', () => {
    service.add(makeMovie());

    service.toggleWatched(42);

    expect(service.items()[0].seen).toBe(true);
    expect(service.watchedCount()).toBe(1);

    service.toggleWatched(42);

    expect(service.items()[0].seen).toBe(false);
    expect(service.watchedCount()).toBe(0);
  });

  it('only toggles the movie with the given id', () => {
    service.add(makeMovie({ id: 1 }));
    service.add(makeMovie({ id: 2 }));

    service.toggleWatched(1);

    expect(service.items().map(item => item.seen)).toEqual([true, false]);
  });

  it('ignores toggleWatched for unknown ids', () => {
    service.add(makeMovie());

    service.toggleWatched(999);

    expect(service.items()[0].seen).toBe(false);
    expect(service.watchedCount()).toBe(0);
  });

  it('removes movies by id', () => {
    service.add(makeMovie({ id: 1 }));
    service.add(makeMovie({ id: 2 }));

    service.remove(1);

    expect(service.items().map(item => item.id)).toEqual([2]);
    expect(service.count()).toBe(1);
  });

  it('counts only seen movies in watchedCount', () => {
    service.add(makeMovie({ id: 1 }));
    service.add(makeMovie({ id: 2 }));
    service.add(makeMovie({ id: 3 }));
    service.toggleWatched(1);
    service.toggleWatched(2);

    expect(service.watchedCount()).toBe(2);
  });

  it('persists the seen flag to localStorage', async () => {
    service.add(makeMovie());
    service.toggleWatched(42);

    await flushEffects();

    expect(JSON.parse(localStorage.getItem('watchlist') ?? '[]')).toEqual([
      { id: 42, title: 'The Movie', poster_path: '/poster.jpg', release_date: '2024-01-01', seen: true },
    ]);
  });
});

describe('WatchlistStore persistence', () => {
  it('restores items that were persisted under the seen key', () => {
    localStorage.clear();
    localStorage.setItem('watchlist', JSON.stringify([
      { id: 1, title: 'Seen Movie', seen: true },
      { id: 2, title: 'Unseen Movie', seen: false },
    ]));

    TestBed.configureTestingModule({});
    const store = TestBed.inject(WatchlistStore);

    expect(store.items()).toEqual([
      { id: 1, title: 'Seen Movie', seen: true },
      { id: 2, title: 'Unseen Movie', seen: false },
    ]);
    expect(store.count()).toBe(2);
    expect(store.watchedCount()).toBe(1);
  });
});
```

